using System.Collections.Immutable;
using Aict.Beta;
using Aict.Core;
using Aict.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace Aict.Core.Tests;
[TestClass] public class ManualViewingTests {
    sealed class Clock:IClock {public string BootId=>"manual-test";public long Uptime{get;set;}public long AwakeMilliseconds=>Uptime;public DateTimeOffset UtcNow=>DateTimeOffset.Parse("2026-11-11T02:00:00Z").AddMilliseconds(Uptime);}
    static RuleGroup Group()=>new(){Id=Guid.NewGuid(),Name="视频额度",WebsiteMode=TargetMode.BlockSelected,WebsiteDomains=["*example.invalid*"],WebsiteExceptions=["example.invalid/lesson"],DailyQuota=TimeSpan.FromSeconds(3)};
    static ManualViewingSample Sample(params string[] urls)=>new(ManualObservation.Confirmed,urls.ToImmutableArray(),0,0,"",[],"committed_document_urls_observed");
    static Authority New(Clock c){string dir=Path.Combine(Environment.GetEnvironmentVariable("AICT_TEST_ROOT")??Path.GetTempPath(),"manual-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);return new(StateRepository.CreateNew(Path.Combine(dir,"engine.sqlite"),Authority.Initial(c)),c,[]);}
    static async Task Set(Authority a,RuleGroup g){var s=(await a.Handle(new())).Status!;Assert.IsTrue((await a.Handle(new(){Command=Command.SubmitPolicy,EditToken=s.EditToken,Policy=new(){ChangeDelay=TimeSpan.Zero,Groups=[g]}})).Ok);}
    static Task<Response> Pulse(Authority a,ManualViewingSample sample,bool trusted=true)=>a.Handle(new(){Command=Command.ManualViewingPulse,ManualViewing=sample},trustedViewer:trusted,viewerProtected:true);
    [TestMethod] public async Task ManualObservationRequiresTheViewerPeerAndDoesNotChangeRules(){var c=new Clock();using var a=New(c);var g=Group();await Set(a,g);var s=(await a.Handle(new())).Status!;Assert.AreEqual("UNAUTHORIZED",(await Pulse(a,Sample("https://example.invalid/watch"),false)).Code);Assert.IsTrue((await Pulse(a,Sample("https://example.invalid/watch"))).Ok);Assert.AreEqual(s.Policy,(await a.Handle(new())).Status!.Policy);}
    [TestMethod] public async Task VisiblePassiveVideoUsesQuotaButOrdinaryChatAndBackgroundAiDoNot(){var c=new Clock();using var a=New(c);await Set(a,Group());await a.Handle(new(){Command=Command.AgentPulse,Agent=new(null,false,500,"ChatGPTIab")},true);await Pulse(a,Sample("https://example.invalid/watch"));c.Uptime=1000;Assert.AreEqual(TimeSpan.FromSeconds(1).Ticks,(await a.Handle(new())).Status!.Usage.Single().UsedTicks);await Pulse(a,new(ManualObservation.OutsideClient,[],0,0,"",[],"other_application_foreground"));c.Uptime=2000;Assert.AreEqual(TimeSpan.FromSeconds(1).Ticks,(await a.Handle(new())).Status!.Usage.Single().UsedTicks);}
    [TestMethod] public async Task PageExceptionDoesNotChargeAndQuotaExhaustionReturnsMaskDecision(){var c=new Clock();using var a=New(c);await Set(a,Group());await a.Handle(new(){Command=Command.AgentPulse,Agent=new(null,false,500,"ChatGPTIab")},true);await Pulse(a,Sample("https://example.invalid/lesson"));c.Uptime=1000;Assert.AreEqual(0L,(await a.Handle(new())).Status!.Usage.Single().UsedTicks);await Pulse(a,Sample("https://example.invalid/watch"));for(int i=0;i<3;i++){c.Uptime+=1000;await a.Handle(new(){Command=Command.AgentPulse,Agent=new(null,false,500,"ChatGPTIab")},true);var response=await Pulse(a,Sample("https://example.invalid/watch"));if(i==2)Assert.IsTrue(response.ManualViewingPlan!.Pages.Single().Denied);}}
    [TestMethod] public void MultipleVisiblePagesChargeOncePerRuleAndExportDistinctDomains(){var g=Group();var p=new PolicyConfiguration{Groups=[g]};var c=new ActivityContext(){WebsiteUrls=["https://example.invalid/a","https://example.invalid/b"]};var slice=new UsageSlice(DateTimeOffset.Parse("2026-11-11T02:00:00Z"),TimeSpan.FromSeconds(1),c);var ledger=RuleEngine.Account(p,new(),slice);Assert.AreEqual(TimeSpan.FromSeconds(1).Ticks,ledger.Get(g.Id,new(2026,11,11)).KnownTicks);Assert.AreEqual(1,ActivityAccounting.Expand(new(p.TimeZoneId,slice,null)).Count(r=>r.Kind=="site"));}
    [TestMethod] public void ScopedManualGapDoesNotChargeAnUnrelatedWebsite(){var g=Group();var other=g with{Id=Guid.NewGuid(),WebsiteDomains=["elsewhere.invalid"]};var p=new PolicyConfiguration{Groups=[g,other]};var slice=new UsageSlice(DateTimeOffset.Parse("2026-11-11T02:00:00Z"),TimeSpan.FromSeconds(1),new(){WebsiteUrls=["https://example.invalid/watch"]},ObservationKnown:false){GapScopeKnown=true};var l=RuleEngine.Account(p,new(),slice);Assert.AreEqual(TimeSpan.FromSeconds(1).Ticks,l.Get(g.Id,new(2026,11,11)).GapChargedTicks);Assert.AreEqual(0L,l.Get(other.Id,new(2026,11,11)).GapChargedTicks);}
    [TestMethod] public void DecisionsRespectAnotherGroupsDenyAndWhitelist(){var a=Group() with{AlwaysBlock=true};var b=a with{Id=Guid.NewGuid(),WebsiteExceptions=[],WebsiteDomains=["example.invalid/lesson"]};var p=new PolicyConfiguration{Groups=[a,b]};var web=new WebPlan([new(a.Id,a.WebsiteMode,a.WebsiteDomains,a.WebsiteExceptions,[],a.Name),new(b.Id,b.WebsiteMode,b.WebsiteDomains,b.WebsiteExceptions,[],b.Name)],true);Assert.IsTrue(ManualViewingRules.Decide(web,p,["https://example.invalid/lesson"]).Pages.Single().Denied);}
    [TestMethod] public async Task LockScreenAndAnUnconfirmedChatWindowDoNotBecomeMeasuredViewing(){var c=new Clock();using var a=New(c);await Set(a,Group());await a.Handle(new(){Command=Command.AgentPulse,Agent=new(null,true,0,"ChatGPTIab")},true);await Pulse(a,Sample("https://example.invalid/watch"));c.Uptime=1000;Assert.AreEqual(0L,(await a.Handle(new())).Status!.Usage.Single().UsedTicks);await Pulse(a,new(ManualObservation.Unavailable,[],0,0,"",[],"committed_document_url_unavailable"));c.Uptime=4000;await a.Handle(new(){Command=Command.AgentPulse,Agent=new(null,false,0,"ChatGPTIab")},true);c.Uptime=4500;Assert.AreEqual(0L,(await a.Handle(new())).Status!.Usage.Single().KnownTicks);}
    [TestMethod] public void InvalidManualPulseFieldsAreRejected(){Assert.ThrowsExactly<ArgumentException>(()=>new Request{Command=Command.ManualViewingPulse,ManualViewing=Sample("file:///C:/private")}.Validate());Assert.ThrowsExactly<ArgumentException>(()=>new Request{Command=Command.Status,ManualViewing=Sample()}.Validate());Assert.ThrowsExactly<ArgumentException>(()=>new Request{Command=Command.ManualViewingPulse,ManualViewing=Sample() with{RenderedKeys=[null!]}}.Validate());}
}
